import{_ as p,a0 as r,w as l,s as o,ao as h,I as t,x as a,a1 as n,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"如何使用 virsh 命令创建、还原和删除 KVM 虚拟机快照 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 virsh 命令创建、还原和删除 KVM 虚拟机快照 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 virsh 命令创建、还原和删除 KVM 虚拟机快照 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 virsh 命令创建、还原和删除 KVM 虚拟机快照 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20180205 How to Create, Revert and Delete KVM Virtual machine snapshot with virsh command","title":"如何使用 virsh 命令创建、还原和删除 KVM 虚拟机快照","tag":"201805","desc":""},"relativePath":"201805/20180205 How to Create, Revert and Delete KVM Virtual machine snapshot with virsh command.md","filePath":"[post].md"}'),d={name:"201805/20180205 How to Create, Revert and Delete KVM Virtual machine snapshot with virsh command.md"};function c(g,s,m,v,k,u){const e=r("Link");return l(),o("div",null,[s[13]||(s[13]=h(`<h1 id="如何使用-virsh-命令创建、还原和删除-kvm-虚拟机快照" tabindex="-1">如何使用 virsh 命令创建、还原和删除 KVM 虚拟机快照 <a class="header-anchor" href="#如何使用-virsh-命令创建、还原和删除-kvm-虚拟机快照" aria-label="Permalink to “如何使用 virsh 命令创建、还原和删除 KVM 虚拟机快照”">​</a></h1><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/02/KVM-VirtualMachine-Snapshot.jpg" alt="KVM-VirtualMachine-Snapshot"></p><p>在虚拟化平台上进行系统管理工作时，经常需要在开始重大操作比如部署补丁和代码前先设置一个虚拟机<ruby>快照<rt>snapshot</rt></ruby>。</p><p>虚拟机<strong>快照</strong>是特定时间点的虚拟机磁盘的副本。换句话说，快照保存了给定的时间点虚拟机的状态和数据。</p><h3 id="我们可以在哪里使用虚拟机快照" tabindex="-1">我们可以在哪里使用虚拟机快照？ <a class="header-anchor" href="#我们可以在哪里使用虚拟机快照" aria-label="Permalink to “我们可以在哪里使用虚拟机快照？”">​</a></h3><p>如果你在使用基于 <strong>KVM</strong> 的<strong>虚拟机管理程序</strong>，那么可以使用 <code>virsh</code> 命令获取虚拟机或域快照。快照在一种情况下变得非常有用，当你已经在虚拟机上安装或应用了最新的补丁，但是由于某些原因，虚拟机上的程序变得不稳定，开发团队想要还原所有的更改和补丁。如果你在应用补丁之前设置了虚拟机的快照，那么可以使用快照将虚拟机恢复到之前的状态。</p><p><strong>注意：</strong>我们只能对磁盘格式为 <strong>Qcow2</strong> 的虚拟机的进行快照，并且 kvm 的 <code>virsh</code> 命令不支持 raw 磁盘格式，请使用以下命令将原始磁盘格式转换为 qcow2。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># qemu-img convert -f raw -O qcow2 image-name.img image-name.qcow2</span></span></code></pre></div><h3 id="创建-kvm-虚拟机-域-快照" tabindex="-1">创建 KVM 虚拟机（域）快照 <a class="header-anchor" href="#创建-kvm-虚拟机-域-快照" aria-label="Permalink to “创建 KVM 虚拟机（域）快照”">​</a></h3><p>我假设 KVM 管理程序已经在 CentOS 7 / RHEL 7 机器上配置好了，并且有虚拟机正在运行。我们可以使用下面的 <code>virsh</code> 命令列出虚拟机管理程序中的所有虚拟机，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@kvm-hypervisor ~]# virsh list --all</span></span>
<span class="line"><span> Id    Name                           State</span></span>
<span class="line"><span>----------------------------------------------------</span></span>
<span class="line"><span> 94    centos7.0                      running</span></span>
<span class="line"><span> 101   overcloud-controller           running</span></span>
<span class="line"><span> 102   overcloud-compute2             running</span></span>
<span class="line"><span> 103   overcloud-compute1             running</span></span>
<span class="line"><span> 114   webserver                      running</span></span>
<span class="line"><span> 115   Test-MTN                       running</span></span></code></pre></div><p>假设我们想创建 webserver 虚拟机的快照，运行下面的命令，</p><p><strong>语法：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># virsh snapshot-create-as –domain {vm_name} –name {snapshot_name} –description “enter description here”</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@kvm-hypervisor ~]# virsh snapshot-create-as --domain webserver --name webserver_snap --description &quot;snap before patch on 4Feb2018&quot;</span></span>
<span class="line"><span>Domain snapshot webserver_snap created</span></span></code></pre></div><p>创建快照后，我们可以使用下面的命令列出与虚拟机相关的快照：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@kvm-hypervisor ~]# virsh snapshot-list webserver</span></span>
<span class="line"><span> Name                 Creation Time             State</span></span>
<span class="line"><span>------------------------------------------------------------</span></span>
<span class="line"><span> webserver_snap       2018-02-04 15:05:05 +0530 running</span></span>
<span class="line"><span>[root@kvm-hypervisor ~]#</span></span></code></pre></div><p>要列出虚拟机快照的详细信息，请运行下面的 <code>virsh</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@kvm-hypervisor ~]# virsh snapshot-info --domain webserver --snapshotname webserver_snap</span></span>
<span class="line"><span>Name:           webserver_snap</span></span>
<span class="line"><span>Domain:         webserver</span></span>
<span class="line"><span>Current:        yes</span></span>
<span class="line"><span>State:          running</span></span>
<span class="line"><span>Location:       internal</span></span>
<span class="line"><span>Parent:         -</span></span>
<span class="line"><span>Children:       0</span></span>
<span class="line"><span>Descendants:    0</span></span>
<span class="line"><span>Metadata:       yes</span></span></code></pre></div><p>我们可以使用下面的 <code>qemu-img</code> 命令查看快照的大小：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@kvm-hypervisor ~]# qemu-img info /var/lib/libvirt/images/snaptestvm.img</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/02/qemu-img-command-output-kvm.jpg" alt="qemu-img-command-output-kvm"></p><h3 id="还原-kvm-虚拟机快照" tabindex="-1">还原 KVM 虚拟机快照 <a class="header-anchor" href="#还原-kvm-虚拟机快照" aria-label="Permalink to “还原 KVM 虚拟机快照”">​</a></h3><p>假设我们想要将 webserver 虚拟机还原到我们在上述步骤中创建的快照。使用下面的 <code>virsh</code> 命令将 Webserver 虚拟机恢复到其快照 webserver_snap 时。</p><p><strong>语法：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># virsh snapshot-revert {vm_name} {snapshot_name}</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@kvm-hypervisor ~]# virsh snapshot-revert webserver webserver_snap</span></span></code></pre></div><h3 id="删除-kvm-虚拟机快照" tabindex="-1">删除 KVM 虚拟机快照 <a class="header-anchor" href="#删除-kvm-虚拟机快照" aria-label="Permalink to “删除 KVM 虚拟机快照”">​</a></h3><p>要删除 KVM 虚拟机快照，首先使用 <code>virsh snapshot-list</code> 命令获取虚拟机的快照详细信息，然后使用 <code>virsh snapshot-delete</code> 命令删除快照。如下示例所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@kvm-hypervisor ~]# virsh snapshot-list --domain webserver</span></span>
<span class="line"><span> Name                 Creation Time             State</span></span>
<span class="line"><span>------------------------------------------------------------</span></span>
<span class="line"><span> webserver_snap       2018-02-04 15:05:05 +0530 running</span></span>
<span class="line"><span>[root@kvm-hypervisor ~]# virsh snapshot-delete --domain webserver --snapshotname webserver_snap</span></span>
<span class="line"><span>Domain snapshot webserver_snap deleted</span></span></code></pre></div><p>这就是本文的全部内容，我希望你们能够了解如何使用 <code>virsh</code> 命令来管理 KVM 虚拟机快照。请分享你的反馈，并不要犹豫地分享给你的技术朋友🙂</p><hr>`,32)),t("p",null,[s[1]||(s[1]=a("via: ",-1)),n(e,{href:"https://www.linuxtechi.com/create-revert-delete-kvm-virtual-machine-snapshot-virsh-command/"},{default:i(()=>[...s[0]||(s[0]=[a("https://www.linuxtechi.com/create-revert-delete-kvm-virtual-machine-snapshot-virsh-command/",-1)])]),_:1})]),t("p",null,[s[5]||(s[5]=a("作者：",-1)),n(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:i(()=>[...s[2]||(s[2]=[a("Pradeep Kumar",-1)])]),_:1}),s[6]||(s[6]=a(" 译者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:i(()=>[...s[3]||(s[3]=[a("geekpi",-1)])]),_:1}),s[7]||(s[7]=a(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[8]||(s[8]=[a("LCTT",-1)])]),_:1}),s[11]||(s[11]=a(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:i(()=>[...s[9]||(s[9]=[a("Linux中国",-1)])]),_:1}),s[12]||(s[12]=a(" 荣誉推出",-1))])])}const y=p(d,[["render",c]]);export{w as __pageData,y as default};
